import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './AddProduct.css';

const AddProduct = () => {
  const [product, setProduct] = useState({
    name: '',
    price: '',
    quantity: '',
    description: '',
    listingDate: '',
    user_id: '',
    selectedProduct: '',
    cropType: '',
    soilType: '',
    wateringRequirements: '',
    fertilizerUsed: '',
    pestControlMethods: '',
    organicCertification: '',
    climateRequirements: '',
    growthCycle: '',
    packagingType: '',
    storageConditions: '',
    shelfLife: '',
    sustainabilityPractices: '',
    productImage: '',
    farmerLocation: '',
    harvestDate: '',
    plantingDate: ''
  });

  const [errorMessage, setErrorMessage] = useState('');
  const [productList, setProductList] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const fetchProductNames = async () => {
      try {
        const response = await axios.get('http://localhost:8080/api/product-names');
        setProductList(response.data);
      } catch (error) {
        console.error('Error fetching product names:', error);
        setErrorMessage('Failed to load product names.');
      }
    };

    fetchProductNames();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProduct({
      ...product,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!product.user_id || !product.selectedProduct) {
      alert('Please enter a valid user ID and select a product.');
      return;
    }

    try {
      await axios.post(
        'http://localhost:8080/api/products',
        {
          name: product.selectedProduct,
          price: product.price,
          quantity: product.quantity,
          description: product.description,
          listingDate: product.listingDate,
          user: { id: product.user_id },
          cropType: product.cropType,
          soilType: product.soilType,
          wateringRequirements: product.wateringRequirements,
          fertilizerUsed: product.fertilizerUsed,
          pestControlMethods: product.pestControlMethods,
          organicCertification: product.organicCertification,
          climateRequirements: product.climateRequirements,
          growthCycle: product.growthCycle,
          packagingType: product.packagingType,
          storageConditions: product.storageConditions,
          shelfLife: product.shelfLife,
          sustainabilityPractices: product.sustainabilityPractices,
          productImage: product.productImage,
          farmerLocation: product.farmerLocation,
          harvestDate: product.harvestDate,
          plantingDate: product.plantingDate
        },
        {
          headers: { 'Content-Type': 'application/json' },
        }
      );

      alert('Product added successfully!');
      setProduct({
        name: '',
        price: '',
        quantity: '',
        description: '',
        listingDate: '',
        user_id: '',
        selectedProduct: '',
        cropType: '',
        soilType: '',
        wateringRequirements: '',
        fertilizerUsed: '',
        pestControlMethods: '',
        organicCertification: '',
        climateRequirements: '',
        growthCycle: '',
        packagingType: '',
        storageConditions: '',
        shelfLife: '',
        sustainabilityPractices: '',
        productImage: '',
        farmerLocation: '',
        harvestDate: '',
        plantingDate: ''
      });
    } catch (error) {
      console.error('Error adding product:', error);
      alert('Failed to add product.');
      setErrorMessage(error.response?.data?.message || 'An error occurred.');
    }
  };

  const filteredProducts = productList.filter((prod) => {
    const productName = typeof prod === 'object' && prod.name ? prod.name : prod;
    return productName.toLowerCase().includes(searchQuery.toLowerCase());
  });

  return (
    <div className="add-product-container">
      <h1>Add Product</h1>
      <form onSubmit={handleSubmit} className="add-product-form">
        {/* Existing Fields */}
        {/* New Fields */}
        <div className="form-group">
          <label htmlFor="climateRequirements">Climate Requirements</label>
          <input
            type="text"
            name="climateRequirements"
            id="climateRequirements"
            value={product.climateRequirements}
            onChange={handleChange}
            placeholder="Enter climate requirements (e.g., Tropical)"
          />
        </div>
        <div className="form-group">
          <label htmlFor="growthCycle">Growth Cycle</label>
          <input
            type="text"
            name="growthCycle"
            id="growthCycle"
            value={product.growthCycle}
            onChange={handleChange}
            placeholder="Enter growth cycle (e.g., 6 months)"
          />
        </div>
        <div className="form-group">
          <label htmlFor="packagingType">Packaging Type</label>
          <input
            type="text"
            name="packagingType"
            id="packagingType"
            value={product.packagingType}
            onChange={handleChange}
            placeholder="Enter packaging type (e.g., Box, Bag)"
          />
        </div>
        <div className="form-group">
          <label htmlFor="storageConditions">Storage Conditions</label>
          <input
            type="text"
            name="storageConditions"
            id="storageConditions"
            value={product.storageConditions}
            onChange={handleChange}
            placeholder="Enter storage conditions (e.g., Cool, Dry)"
          />
        </div>
        <div className="form-group">
          <label htmlFor="shelfLife">Shelf Life</label>
          <input
            type="text"
            name="shelfLife"
            id="shelfLife"
            value={product.shelfLife}
            onChange={handleChange}
            placeholder="Enter shelf life (e.g., 1 year)"
          />
        </div>
        <div className="form-group">
          <label htmlFor="sustainabilityPractices">Sustainability Practices</label>
          <input
            type="text"
            name="sustainabilityPractices"
            id="sustainabilityPractices"
            value={product.sustainabilityPractices}
            onChange={handleChange}
            placeholder="Enter sustainability practices (e.g., Organic farming)"
          />
        </div>
        <div className="form-group">
          <label htmlFor="farmerLocation">Farmer Location</label>
          <input
            type="text"
            name="farmerLocation"
            id="farmerLocation"
            value={product.farmerLocation}
            onChange={handleChange}
            placeholder="Enter farmer location (e.g., Rajasthan, India)"
          />
        </div>
        <div className="form-group">
          <label htmlFor="harvestDate">Harvest Date</label>
          <input
            type="date"
            name="harvestDate"
            id="harvestDate"
            value={product.harvestDate}
            onChange={handleChange}
          />
        </div>
        <div className="form-group">
          <label htmlFor="plantingDate">Planting Date</label>
          <input
            type="date"
            name="plantingDate"
            id="plantingDate"
            value={product.plantingDate}
            onChange={handleChange}
          />
        </div>

        <button type="submit" className="submit-button">Add Product</button>
      </form>

      {errorMessage && <p className="error-message">{errorMessage}</p>}
    </div>
  );
};

export default AddProduct;
